    }
    if (data.containsKey('created_by')) {
      context.handle(_createdByMeta,
          createdBy.isAcceptableOrUnknown(data['created_by']!, _createdByMeta));
    }
    if (data.containsKey('parcialmente_sincronizada')) {
      context.handle(
          _parcialmenteSincronizadaMeta,
          parcialmenteSincronizada.isAcceptableOrUnknown(
              data['parcialmente_sincronizada']!,
              _parcialmenteSincronizadaMeta));
    }
    if (data.containsKey('projeto_id')) {
      context.handle(_projetoIdMeta,
          projetoId.isAcceptableOrUnknown(data['projeto_id']!, _projetoIdMeta));
    }
    if (data.containsKey('parcela_id_text')) {
      context.handle(
          _parcelaIdTextMeta,
          parcelaIdText.isAcceptableOrUnknown(
              data['parcela_id_text']!, _parcelaIdTextMeta));
    }
    if (data.containsKey('geo_json')) {
      context.handle(_geoJsonMeta,
          geoJson.isAcceptableOrUnknown(data['geo_json']!, _geoJsonMeta));
    }
    if (data.containsKey('area_m2')) {
      context.handle(_areaM2Meta,
          areaM2.isAcceptableOrUnknown(data['area_m2']!, _areaM2Meta));
    }
    if (data.containsKey('unidade_forma')) {
      context.handle(
          _unidadeFormaMeta,
          unidadeForma.isAcceptableOrUnknown(
              data['unidade_forma']!, _unidadeFormaMeta));
    }
    if (data.containsKey('raio_m')) {
      context.handle(
          _raioMMeta, raioM.isAcceptableOrUnknown(data['raio_m']!, _raioMMeta));
    }
    if (data.containsKey('status_parcela')) {
      context.handle(
          _statusParcelaMeta,
          statusParcela.isAcceptableOrUnknown(
              data['status_parcela']!, _statusParcelaMeta));
    }
    if (data.containsKey('marcador')) {
      context.handle(_marcadorMeta,
          marcador.isAcceptableOrUnknown(data['marcador']!, _marcadorMeta));
    }
    if (data.containsKey('protocolo_versao')) {
      context.handle(
          _protocoloVersaoMeta,
          protocoloVersao.isAcceptableOrUnknown(
              data['protocolo_versao']!, _protocoloVersaoMeta));
    }
    if (data.containsKey('substituta_de')) {
