class Parcela extends DataClass implements Insertable<Parcela> {
  final int id;
  final String uuid;
  final String propriedade;
  final String propUt;
  final int idParcela;
  final String? observacoes;
  final double? latitude;
  final double? longitude;
  final String userId;
  final double? areaHa;
  final bool synced;

  /// true = utilizador marcou "concluída" → pode sincronizar; false = rascunho/incompleta
  final bool prontaParaSync;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  final String? deletedBy;

  /// Quem criou esta parcela (uuid do user ou '' para seed/sistema). Usado para filtrar catálogo por usuário.
  final String createdBy;
  final bool parcialmenteSincronizada;
  final String? projetoId;
  final String? parcelaIdText;
  final String? geoJson;
  final double? areaM2;
  final String? unidadeForma;
  final double? raioM;
  final String? statusParcela;
  final String? marcador;
  final String? protocoloVersao;
  final String? substitutaDe;
